import 'package:flutter/material.dart';import 'package:flutter_bloc/flutter_bloc.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import 'package:flutter_svg/svg.dart';import 'package:zan/Core/Resources/app_strings.dart';import '../../../Config/Assets/images.dart';import '../../../Config/Cubit/settings_cubit.dart';import '../../../Core/Resources/app_colors.dart';import '../../../Core/Resources/app_fonts.dart';class LogoAndText extends StatelessWidget {  const LogoAndText({    super.key,    required Animation<double> fadeAnimation,    required this.time,  }) : _fadeAnimation = fadeAnimation;  final double time;  final Animation<double> _fadeAnimation;  @override  Widget build(BuildContext context) {    return Positioned(      right: 0,      left: 0,      top: 148.h,      child: AnimatedBuilder(        animation: _fadeAnimation,        builder: (context, child) => Opacity(          opacity: _fadeAnimation.value,          child: child,        ),        child: Column(          children: [            SvgPicture.asset(              context.watch<SettingsCubit>().state.themeMode == ThemeMode.light                  ? AppImages.logoLightMode                  : AppImages.logoDarkMode,              height: 60.h,              width: 60.w,            ),            time < 0.02                ? Container()                : Padding(                    padding: const EdgeInsets.all(15.0),                    child: Text(                      AppStrings.titleLogoSplash,                      style: AppTextStyles.bodyMediumMedium.copyWith(                        color: AppColors.white,                        height: 1.57,                        letterSpacing: 0.07,                      ),                    ),                  ),          ],        ),      ),    );  }}